<?php

namespace App\Domains\Api\Filament\Resources\WebhookEndpoints\RelationManagers;

use Filament\Resources\RelationManagers\RelationManager;
use Filament\Tables\Columns\TextColumn;
use Filament\Tables\Table;

/**
 * S21 B6 — the "delivery log" the plan's own checklist names. Read-only:
 * rows are system-generated by `WebhookDispatcher`/`DeliverWebhook`, never
 * created or edited by hand, so no headerActions/recordActions at all.
 */
class DeliveriesRelationManager extends RelationManager
{
    protected static string $relationship = 'deliveries';

    public function table(Table $table): Table
    {
        return $table
            ->recordTitleAttribute('event_type')
            ->columns([
                TextColumn::make('event_type'),
                TextColumn::make('status')
                    ->badge()
                    ->color(fn (string $state): string => match ($state) {
                        'delivered' => 'success',
                        'failed' => 'danger',
                        default => 'warning',
                    }),
                TextColumn::make('attempt_count')->label('Attempts'),
                TextColumn::make('last_attempted_at')->dateTime()->placeholder('Never'),
                TextColumn::make('delivered_at')->dateTime()->placeholder('—'),
                TextColumn::make('created_at')->dateTime()->sortable(),
            ])
            ->defaultSort('created_at', 'desc');
    }
}
